{
  "requirements": [
    {
      "target_id": "t0",
      "policy_source_id": "q23",
      "policy_quote": "the prescription status is `active`;",
      "requirement": "The prescription must have an `active` status."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q23",
      "policy_quote": "`refills_remaining` is at least 1;",
      "requirement": "The prescription must have at least 1 refill remaining."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q23",
      "policy_quote": "the current date is not after `expiry_date`;",
      "requirement": "The current date must not be after the prescription's `expiry_date`."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q23",
      "policy_quote": "at least 75% of the `days_supply` of the most recent fill has elapsed since `last_fill_date` (refill-too-soon rule).",
      "requirement": "At least 75% of the `days_supply` must have elapsed since the `last_fill_date` (e.g., for a 30-day supply, at least 22.5 days must have passed)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q23",
      "policy_quote": "The quantity of a refill must equal the `quantity_per_fill` of the prescription.",
      "requirement": "The requested refill quantity must exactly match the prescription's `quantity_per_fill`."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q23",
      "policy_quote": "Prescriptions with `schedule` equal to `C-II` (controlled substances) can never be refilled through this channel.",
      "requirement": "The prescription must not be a controlled substance (`schedule` not equal to `C-II`)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q23",
      "policy_quote": "Orders are shipped only to the address currently on file for the patient. The `ship_to` argument of `request_refill` must be exactly the address on file.",
      "requirement": "The `ship_to` address must exactly match the patient's address on file."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q23",
      "policy_quote": "Before any action that changes data (`request_refill`), list the action details and obtain explicit user confirmation (\"yes\"/\"да\") for those exact details.",
      "requirement": "Explicit user confirmation must be obtained for the exact refill details before proceeding."
    }
  ]
}
